import { runScript } from '../../sdk/runner';

await runScript(async ({ bot, sdk }) => {
    const st = sdk.getState()!;
    const p = st.player!;
    console.log(`POS ${p.worldX},${p.worldZ} plane=${p.level} hp=${p.hp}/${p.maxHp} cb=${p.combatLevel}`);
    console.log('SKILLS: ' + st.skills.map(s => `${s.name}:${s.baseLevel}`).join(' '));
    console.log('INV: ' + st.inventory.map(i => `${i.name}x${i.count}(s${i.slot})`).join(', '));
    console.log('EQUIP: ' + st.equipment.map(i => `${i.name}(s${i.slot})`).join(', '));
    console.log('STYLE: ' + JSON.stringify(st.combatStyle));
    console.log('NPCS: ' + st.nearbyNpcs.map(n => `${n.name}#${n.index}(cb${n.combatLevel} hp${n.hp}/${n.maxHp} d${n.distance})`).join(' | '));

    // test attack nearest man/rat and measure
    const target = st.nearbyNpcs
        .filter(n => /man|rat/i.test(n.name))
        .filter(n => n.optionsWithIndex.some(o => /attack/i.test(o.text)))
        .sort((a, b) => a.distance - b.distance)[0];
    if (!target) { console.log('no target'); return; }
    console.log(`ATTACK ${target.name} idx${target.index} hp${target.maxHp}`);
    const startTick = sdk.getState()!.tick;
    const res = await bot.attack(target, 20000);
    console.log('attack result ' + JSON.stringify(res));
    const endTick = sdk.getState()!.tick;
    console.log(`ticks elapsed ${endTick - startTick}`);
    const st2 = sdk.getState()!;
    console.log(`AFTER hp=${st2.player!.hp}/${st2.player!.maxHp} atkxp=${sdk.getSkillXp('attack')} strxp=${sdk.getSkillXp('strength')} defxp=${sdk.getSkillXp('defence')}`);
}, { timeout: 60_000 });

import { runScript } from '../../sdk/runner';

const PATTERN = process.argv[2] || 'cow|goblin|rat|man|woman';
const SECONDS = parseInt(process.argv[3] || '60', 10);

await runScript(async ({ bot, sdk }) => {
    const re = new RegExp(PATTERN, 'i');
    // equip best melee
    for (const name of ['Bronze sword', 'Wooden shield']) {
        const it = sdk.findInventoryItem(new RegExp('^' + name + '$', 'i'));
        if (it) { const r = await bot.equipItem(it); console.log(`equip ${name}: ${r.success}`); }
    }

    const start = Date.now();
    const end = start + SECONDS * 1000;
    let kills = 0;
    let lastKillHp = 0;
    let lastTarget = '';
    let swings = 0;

    const startXp = {
        atk: sdk.getSkillXp('attack') ?? 0,
        str: sdk.getSkillXp('strength') ?? 0,
        def: sdk.getSkillXp('defence') ?? 0,
        hp: sdk.getSkillXp('hitpoints') ?? 0,
    };
    const startTick = sdk.getState()!.tick;

    while (Date.now() < end) {
        const st = sdk.getState();
        if (!st?.player) { await sdk.waitForTicks(2); continue; }
        if (st.player.isDead) { console.log('DIED'); await sdk.waitForTicks(20); continue; }
        // eat if hurt
        if (st.player.hp <= 4) {
            const food = sdk.findInventoryItem(/bread|shrimp/i);
            if (food) { const e = await bot.eatFood(food); console.log(`ate hp+${e.hpGained}`); }
        }
        // if in combat, just wait
        if (st.player.combat.inCombat) { await sdk.waitForTicks(1); continue; }
        const target = st.nearbyNpcs
            .filter(n => re.test(n.name))
            .filter(n => n.optionsWithIndex.some(o => /attack/i.test(o.text)))
            .filter(n => n.reachable !== false)
            .sort((a, b) => a.distance - b.distance)[0];
        if (!target) { await sdk.waitForTicks(2); continue; }
        try {
            const r = await bot.attack(target, 8000);
            swings++;
            lastTarget = `${target.name}(cb${target.combatLevel})`;
            if (r.success) {
                // wait until combat ends
                const t0 = sdk.getState()!.tick;
                for (let i = 0; i < 40; i++) {
                    const s2 = sdk.getState()!;
                    if (!s2.player?.combat.inCombat) break;
                    await sdk.waitForTicks(2);
                }
                kills++;
            }
        } catch (e) { /* continue */ }
    }
    const endXp = {
        atk: sdk.getSkillXp('attack') ?? 0,
        str: sdk.getSkillXp('strength') ?? 0,
        def: sdk.getSkillXp('defence') ?? 0,
        hp: sdk.getSkillXp('hitpoints') ?? 0,
    };
    const endTick = sdk.getState()!.tick;
    const secs = (endTick - startTick) * 0.6;
    console.log(`DONE ${lastTarget} kills~${kills} swings${swings} gameSec=${secs.toFixed(0)}`);
    console.log(`XP atk+${endXp.atk - startXp.atk} str+${endXp.str - startXp.str} def+${endXp.def - startXp.def} hp+${endXp.hp - startXp.hp}`);
    const p = sdk.getState()!.player!;
    console.log(`LVL atk=${sdk.getSkill('attack')!.baseLevel} str=${sdk.getSkill('strength')!.baseLevel} def=${sdk.getSkill('defence')!.baseLevel} hp=${sdk.getSkill('hitpoints')!.baseLevel} cb=${p.combatLevel}`);
}, { timeout: (SECONDS + 30) * 1000 });

import { runScript } from '../../sdk/runner';

const TRAIN_SEC = parseInt(process.argv[2] || '70', 10);
const TOTAL_SEC = parseInt(process.argv[3] || '180', 10);

await runScript(async ({ bot, sdk }) => {
    for (const name of ['Bronze sword', 'Wooden shield']) {
        const it = sdk.findInventoryItem(new RegExp('^' + name + '$', 'i'));
        if (it) await bot.equipItem(it);
    }
    const st0 = sdk.getState()!;
    console.log('STYLES: ' + JSON.stringify(st0.combatStyle?.styles));
    // prefer controlled, else aggressive
    const style = st0.combatStyle?.styles.find(s => /controlled/i.test(s.type)) ??
        st0.combatStyle?.styles.find(s => /aggressive/i.test(s.type));
    if (style) { await sdk.sendSetCombatStyle(style.index); console.log('style=' + style.name + ' ' + style.type); }

    const start = Date.now();
    const trainEnd = start + TRAIN_SEC * 1000;
    const hardEnd = start + TOTAL_SEC * 1000;

    async function eatIfNeeded() {
        const st = sdk.getState();
        if (st?.player && st.player.hp <= 6) {
            const food = sdk.findInventoryItem(/bread|shrimp/i);
            if (food) { const e = await bot.eatFood(food); console.log(`ate +${e.hpGained} -> ${sdk.getState()!.player!.hp}`); return true; }
        }
        return false;
    }

    async function attackLoop(re, untilMs, label) {
        let n = 0;
        while (Date.now() < untilMs) {
            const st = sdk.getState();
            if (!st?.player) { await sdk.waitForTicks(2); continue; }
            if (st.player.isDead) { console.log('DIED'); await sdk.waitForTicks(30); continue; }
            await eatIfNeeded();
            if (st.player.combat.inCombat) { await sdk.waitForTicks(1); continue; }
            const cands = st.nearbyNpcs
                .filter(x => re.test(x.name))
                .filter(x => x.optionsWithIndex.some(o => /attack/i.test(o.text)))
                .filter(x => x.reachable !== false);
            if (!cands.length) { await sdk.waitForTicks(2); continue; }
            const t = cands.sort((a, b) => a.distance - b.distance)[0];
            try {
                const r = await bot.attack(t, 8000);
                n++;
                if (n % 3 === 0) console.log(`[${label}] ${t.name} cb${t.combatLevel} ok=${r.success} n=${n}`);
                for (let i = 0; i < 30; i++) { const s2 = sdk.getState()!; if (!s2.player?.combat.inCombat) break; await sdk.waitForTicks(2); }
            } catch { }
        }
        return n;
    }

    const t1 = await attackLoop(/man|rat|woman|goblin/i, trainEnd, 'train');
    const st1 = sdk.getState()!;
    console.log(`TRAINED n=${t1} atk=${sdk.getSkill('attack')!.baseLevel} str=${sdk.getSkill('strength')!.baseLevel} def=${sdk.getSkill('defence')!.baseLevel} hp=${sdk.getSkill('hitpoints')!.baseLevel} cb=${st1.player!.combatLevel}`);

    // Phase 2: strongest nearby attackable, prefer suit of armour / guard / higher level
    const t2 = await attackLoop(/suit of armour|guard|man|woman|rat/i, hardEnd, 'hard');
    const st2 = sdk.getState()!;
    console.log(`HARD n=${t2} hp=${st2.player!.hp}/${st2.player!.maxHp} cb=${st2.player!.combatLevel}`);
    console.log('NEAR: ' + st2.nearbyNpcs.filter(x => /suit|guard/i.test(x.name)).map(x => `${x.name} cb${x.combatLevel} hp${x.hp}/${x.maxHp} d${x.distance}`).join(' | '));
}, { timeout: (TOTAL_SEC + 30) * 1000 });

